begin;
create extension if not exists pgtap;
select plan(30);
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values
('f0090000-0000-4000-8000-000000000001','authenticated','authenticated','fin-qa009@example.test','',now(),now(),now());
insert into public.workspaces(id,name) values('f0090000-0000-4000-8000-000000000002','FIN QA009 synthetic');
insert into public.workspace_users(workspace_id,user_id,role) values('f0090000-0000-4000-8000-000000000002','f0090000-0000-4000-8000-000000000001','admin');
insert into public.cycles(id,workspace_id,year,name,starts_on,closes_on,status) values
('f0090000-0000-4000-8000-000000000003','f0090000-0000-4000-8000-000000000002',2026,'QA009','2026-01-01','2026-12-05','active');
insert into public.members(id,workspace_id,display_name) values('f0090000-0000-4000-8000-000000000004','f0090000-0000-4000-8000-000000000002','Borrower QA009');
insert into public.cycle_members(id,workspace_id,cycle_id,member_id,monthly_quota) values
('f0090000-0000-4000-8000-000000000005','f0090000-0000-4000-8000-000000000002','f0090000-0000-4000-8000-000000000003','f0090000-0000-4000-8000-000000000004',100000);
set local natillera.civil_today='2026-10-16';
set local role authenticated;
set local request.jwt.claim.sub='f0090000-0000-4000-8000-000000000001';
select public.create_bank_account('f0090000-0000-4000-8000-000000000003','QA009 bank','','');
select public.record_bank_opening('f0090000-0000-4000-8000-000000000003',(select id from public.bank_accounts where display_name='QA009 bank'),'qa009-opening','2026-08-01',1000000,'synthetic financing');
select public.record_internal_liquidity_transfer('f0090000-0000-4000-8000-000000000003','qa009-cash','2026-08-01','bank',(select id from public.bank_accounts where display_name='QA009 bank'),'cash',null,1000000,'synthetic liquidity');
create temporary table qa009_loan as select id from public.create_loan_contract('f0090000-0000-4000-8000-000000000003','qa009-loan','f0090000-0000-4000-8000-000000000004',null,null,60000,'amortized','EA',0.12,2,'2026-09-01');
select public.confirm_loan_disbursement((select id from qa009_loan),'qa009-disburse','2026-09-01');
create temporary table qa009_stale_quote as select public.quote_loan_prepayment((select id from qa009_loan),'2026-10-15') q;
select is((public.quote_loan_prepayment((select id from qa009_loan),'2026-09-01')->>'interest_due')::numeric,0::numeric,'same-day EA prepayment has zero days');
select is((public.quote_loan_payment((select id from qa009_loan),'2026-10-01',100)->>'interest_amount')::numeric,100::numeric,'partial payment first covers interest');
select public.record_loan_payment((select id from qa009_loan),'qa009-partial','2026-10-01',100,0,100,'regular');
select is((select status from public.loan_schedule_progress where loan_id=(select id from qa009_loan) and installment_number=1),'projected','partial interest does not close quota');
select is((public.quote_loan_prepayment((select id from qa009_loan),'2026-10-01')->>'interest_due')::numeric,461.49::numeric,'partial interest is deducted without resetting period coverage');
select is((public.quote_loan_prepayment((select id from qa009_loan),'2026-10-01')->>'interest_covered_until')::date,'2026-09-01'::date,'partial payment does not invent a fully covered date');
select throws_ok($$select public.record_loan_payment((select id from qa009_loan),'qa009-bad-split','2026-10-01',100,100,0,'regular')$$,'P0001','La aplicacion debe cubrir primero intereses exigibles y despues capital, desde la cuota mas antigua.','server rejects capital before exigible interest');
select public.record_loan_payment((select id from qa009_loan),'qa009-first-complete','2026-10-01',29900,29438.51,461.49,'regular');
select is((select status from public.loan_schedule_progress where loan_id=(select id from qa009_loan) and installment_number=1),'paid','exact full first quota derives paid');
select is((select status from public.loan_schedule_progress where loan_id=(select id from qa009_loan) and installment_number=2),'projected','future quota remains open');
select lives_ok($$select public.record_loan_payment((select id from qa009_loan),'qa009-first-complete','2026-10-01',29900,29438.51,461.49,'regular')$$,'retry is resolved before recalculating dues');
select is((select count(*) from public.loan_payments where idempotency_key='qa009-first-complete'),1::bigint,'retry creates no duplicate payment');
select is((select sum(capital_amount+interest_amount) from public.loan_payment_applications where loan_id=(select id from qa009_loan)),30000::numeric,'explicit applications conserve payment totals');
select throws_ok($$select public.quote_loan_payment((select id from qa009_loan),'2026-10-01',1)$$,'P0001','El pago excede las cuotas exigibles. Los abonos extraordinarios requieren definir reduccion de plazo o cuota.','extraordinary excess is blocked');
select is((public.quote_loan_prepayment((select id from qa009_loan),'2026-10-15')->>'interest_due')::numeric,133.14::numeric,'remaining capital accrues 14 uncovered days');
select is((public.quote_loan_prepayment((select id from qa009_loan),'2026-10-15')->>'interest_covered_until')::date,'2026-10-01'::date,'fully paid interest covers through actual quota end');
select is((public.quote_loan_prepayment((select id from qa009_loan),'2026-10-15')->>'principal_due')::numeric,30561.49::numeric,'outstanding principal is unchanged by schedule projection');
select throws_ok($$select public.confirm_loan_prepayment((select id from qa009_loan),'qa009-stale','2026-10-15',(select q->>'quote_hash' from qa009_stale_quote))$$,'P0001','La cotizacion cambio. Vuelva a calcular antes de confirmar el prepago.','stale quote cannot be silently confirmed');
select throws_ok($$select public.confirm_loan_prepayment((select id from qa009_loan),'qa009-no-quote','2026-10-15',null)$$,'P0001','La cotizacion cambio. Vuelva a calcular antes de confirmar el prepago.','new API requires the visible quote hash');
create temporary table qa009_final_quote as select public.quote_loan_prepayment((select id from qa009_loan),'2026-10-15') q;
select public.confirm_loan_prepayment((select id from qa009_loan),'qa009-prepay','2026-10-15',(select q->>'quote_hash' from qa009_final_quote));
select is((select amount from public.loan_payments where idempotency_key='qa009-prepay'),30694.63::numeric,'confirmation uses exactly the SQL quote');
select lives_ok($$select public.confirm_loan_prepayment((select id from qa009_loan),'qa009-prepay','2026-10-15',(select q->>'quote_hash' from qa009_final_quote))$$,'prepayment retry works after contract is paid');
select is((select calculation_snapshot->>'quote_hash' from public.loan_payments where idempotency_key='qa009-prepay'),(select q->>'quote_hash' from qa009_final_quote),'posted payment retains the exact quotation snapshot');
select is((select count(*) from public.loan_payments where idempotency_key='qa009-prepay'),1::bigint,'prepayment has one payment');
select is((select status from public.loan_contracts where id=(select id from qa009_loan)),'paid','full prepayment closes loan');
select is((select count(*) from public.loan_payments where idempotency_key='qa009-bad-split'),0::bigint,'rejected split leaves no row');
select is((select count(*) from (select operation_id from public.ledger_entries where cycle_id='f0090000-0000-4000-8000-000000000003' group by operation_id having sum(amount)<>0) s),0::bigint,'all payment operations balance');
select is((select -sum(le.amount) from public.ledger_entries le join public.financial_operations fo on fo.id=le.operation_id where fo.id=(select operation_id from public.loan_payments where idempotency_key='qa009-prepay') and le.account='admin_payable'),13.31::numeric,'10 percent administration retained on actual accrued interest');
create temporary table qa008_p013 as select id from public.create_loan_contract('f0090000-0000-4000-8000-000000000003','qa008-p013','f0090000-0000-4000-8000-000000000004',null,null,60000,'amortized','EA',0.12,2,'2026-09-01');
select public.set_loan_settlement_agreement((select id from qa008_p013),'P013_FIRST_MONTH');
select public.confirm_loan_disbursement((select id from qa008_p013),'qa008-p013-disburse','2026-09-01');
select is((public.quote_loan_prepayment((select id from qa008_p013),'2026-09-02')->>'interest_due')::numeric,561.49::numeric,'P013 preserves first month contract interest even at one day');
select is(public.quote_loan_prepayment((select id from qa008_p013),'2026-10-15')->>'rule_version','P013_FIRST_MONTH','P013 exception remains explicit');
select public.record_loan_payment((select id from qa008_p013),'qa008-p013-interest','2026-10-01',561.49,0,561.49,'regular');
select is((public.quote_loan_prepayment((select id from qa008_p013),'2026-10-15')->>'interest_due')::numeric,0::numeric,'P013 never charges an already paid first month twice');
reset role;
update public.loan_contracts set settlement_agreement_code=null,legacy_paid_interest_amount=100 where id=(select id from qa008_p013);
set local role authenticated;
select throws_ok($$select public.quote_loan_prepayment((select id from qa008_p013),'2026-10-15')$$,'P0001','Los intereses historicos no tienen periodo verificado. Concilie la cobertura antes de cotizar el prepago EA.','unknown historical coverage is blocked instead of guessing');
select is((select count(*) from public.loan_payments where loan_id=(select id from qa008_p013)),1::bigint,'coverage rejection creates no financial operation');
select * from finish();
rollback;
